CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_declarationquestionresponse]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_declarationquestionresponse]
	(
		[apuk_applicationid],
		[apuk_applicationid_entitytype],
		[apuk_applicationidname],
		[apuk_declarationaccepted],
		[apuk_declarationquestionid],
		[apuk_declarationquestionid_entitytype],
		[apuk_declarationquestionidname],
		[apuk_declarationquestionresponseid],
		[apuk_declarationsubmitted],
		[apuk_declarationversionnumber],
		[apuk_enrolmentid],
		[apuk_enrolmentid_entitytype],
		[apuk_enrolmentidname],
		[apuk_name],
		[apuk_originatingdeclaration],
		[apuk_response],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_applicationid],
		stg.[apuk_applicationid_entitytype],
		stg.[apuk_applicationidname],
		stg.[apuk_declarationaccepted],
		stg.[apuk_declarationquestionid],
		stg.[apuk_declarationquestionid_entitytype],
		stg.[apuk_declarationquestionidname],
		stg.[apuk_declarationquestionresponseid],
		stg.[apuk_declarationsubmitted],
		stg.[apuk_declarationversionnumber],
		stg.[apuk_enrolmentid],
		stg.[apuk_enrolmentid_entitytype],
		stg.[apuk_enrolmentidname],
		stg.[apuk_name],
		stg.[apuk_originatingdeclaration],
		stg.[apuk_response],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_declarationquestionresponse] stg
		LEFT JOIN [synapse_ce].[apuk_declarationquestionresponse] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
